// (model plugins/net/frr/Quagga/BFD.xml, array neighbors.neighbor).
type FrrBfdNeighbor struct {
	Enabled          Bool   `json:"enabled"`
	Description      string `json:"description"`
	Address          string `json:"address"`
	Multihop         Bool   `json:"multihop"`
	LocalAddress     string `json:"localaddress"`
	Interface        Option `json:"interfacename"`
	DetectMultiplier Int    `json:"detect_multiplier"`
	ReceiveInterval  Int    `json:"receive_interval"`
	TransmitInterval Int    `json:"transmit_interval"`
}

func (v *FrrBfdNeighbor) IsZero() bool { return v.Address == "" }

// FrrBfdNeighborRow is one row of a frr_bfd_neighbor search; values are display text. Sensitive fields are left out.
type FrrBfdNeighborRow struct {
	UUID             Text `json:"uuid"`
	Enabled          Text `json:"enabled"`
	Description      Text `json:"description"`
	Address          Text `json:"address"`
	Multihop         Text `json:"multihop"`
	LocalAddress     Text `json:"localaddress"`
	Interface        Text `json:"interfacename"`
	DetectMultiplier Text `json:"detect_multiplier"`
	ReceiveInterval  Text `json:"receive_interval"`
	TransmitInterval Text `json:"transmit_interval"`
}

func (r FrrBfdNeighborRow) RowRef() (string, string) { return string(r.UUID), string(r.Address) }

// FrrStaticRoute: A static route in FRR's staticd (Routing → Static).
// (model plugins/net/frr/Quagga/STATICd.xml, array routes.route).
type FrrStaticRoute struct {
	Enabled   Bool   `json:"enabled"`
	Network   string `json:"network"`
	Gateway   string `json:"gateway"`
	Interface Option `json:"interfacename"`
	Bfd       Bool   `json:"bfd"`
}

func (v *FrrStaticRoute) IsZero() bool { return v.Network == "" }

// FrrStaticRouteRow is one row of a frr_static_route search; values are display text. Sensitive fields are left out.
type FrrStaticRouteRow struct {
	UUID      Text `json:"uuid"`
	Enabled   Text `json:"enabled"`
	Network   Text `json:"network"`
	Gateway   Text `json:"gateway"`
	Interface Text `json:"interfacename"`
	Bfd       Text `json:"bfd"`
}

func (r FrrStaticRouteRow) RowRef() (string, string) { return string(r.UUID), string(r.Network) }

