// FRRService manages Routing → FRR (plugin os-frr).
type FRRService struct {
	c                    *Client
	BgpNeighbors         *ItemController[FrrBgpNeighbor, FrrBgpNeighborRow]
	BgpPeerGroups        *ItemController[FrrBgpPeerGroup, FrrBgpPeerGroupRow]
	BgpAspaths           *ItemController[FrrBgpAspath, FrrBgpAspathRow]
	BgpCommunityLists    *ItemController[FrrBgpCommunityList, FrrBgpCommunityListRow]
	BgpPrefixLists       *ItemController[FrrBgpPrefixList, FrrBgpPrefixListRow]
	BgpRouteMaps         *ItemController[FrrBgpRouteMap, FrrBgpRouteMapRow]
	BgpRedistributions   *ItemController[FrrBgpRedistribution, FrrBgpRedistributionRow]
	OspfAreas            *ItemController[FrrOspfArea, FrrOspfAreaRow]
	OspfNetworks         *ItemController[FrrOspfNetwork, FrrOspfNetworkRow]
	OspfNeighbors        *ItemController[FrrOspfNeighbor, FrrOspfNeighborRow]
	OspfInterfaces       *ItemController[FrrOspfInterface, FrrOspfInterfaceRow]
	OspfPrefixLists      *ItemController[FrrOspfPrefixList, FrrOspfPrefixListRow]
	OspfRouteMaps        *ItemController[FrrOspfRouteMap, FrrOspfRouteMapRow]
	OspfRedistributions  *ItemController[FrrOspfRedistribution, FrrOspfRedistributionRow]
	Ospf6Areas           *ItemController[FrrOspf6Area, FrrOspf6AreaRow]
	Ospf6Interfaces      *ItemController[FrrOspf6Interface, FrrOspf6InterfaceRow]
	Ospf6PrefixLists     *ItemController[FrrOspf6PrefixList, FrrOspf6PrefixListRow]
	Ospf6RouteMaps       *ItemController[FrrOspf6RouteMap, FrrOspf6RouteMapRow]
	Ospf6Redistributions *ItemController[FrrOspf6Redistribution, FrrOspf6RedistributionRow]
	BfdNeighbors         *ItemController[FrrBfdNeighbor, FrrBfdNeighborRow]
	StaticRoutes         *ItemController[FrrStaticRoute, FrrStaticRouteRow]
	General              *SettingsController[FrrGeneral]
	BgpSettings          *SettingsController[FrrBgp]
	OspfSettings         *SettingsController[FrrOspf]
	Ospf6Settings        *SettingsController[FrrOspf6]
	RipSettings          *SettingsController[FrrRip]
	BfdSettings          *SettingsController[FrrBfd]
	StaticSettings       *SettingsController[FrrStatic]
}

func newFRRService(c *Client) *FRRService {
	return &FRRService{
		c:                    c,
		BgpNeighbors:         NewItemController[FrrBgpNeighbor, FrrBgpNeighborRow](c, "quagga/bgp", "neighbor", "Neighbor", nil, "quagga/service/reconfigure"),
		BgpPeerGroups:        NewItemController[FrrBgpPeerGroup, FrrBgpPeerGroupRow](c, "quagga/bgp", "peergroup", "Peergroup", nil, "quagga/service/reconfigure"),
		BgpAspaths:           NewItemController[FrrBgpAspath, FrrBgpAspathRow](c, "quagga/bgp", "aspath", "Aspath", nil, "quagga/service/reconfigure"),
		BgpCommunityLists:    NewItemController[FrrBgpCommunityList, FrrBgpCommunityListRow](c, "quagga/bgp", "communitylist", "Communitylist", nil, "quagga/service/reconfigure"),
		BgpPrefixLists:       NewItemController[FrrBgpPrefixList, FrrBgpPrefixListRow](c, "quagga/bgp", "prefixlist", "Prefixlist", nil, "quagga/service/reconfigure"),
		BgpRouteMaps:         NewItemController[FrrBgpRouteMap, FrrBgpRouteMapRow](c, "quagga/bgp", "routemap", "Routemap", nil, "quagga/service/reconfigure"),
		BgpRedistributions:   NewItemController[FrrBgpRedistribution, FrrBgpRedistributionRow](c, "quagga/bgp", "redistribution", "Redistribution", nil, "quagga/service/reconfigure"),
		OspfAreas:            NewItemController[FrrOspfArea, FrrOspfAreaRow](c, "quagga/ospfsettings", "area", "Area", nil, "quagga/service/reconfigure"),
		OspfNetworks:         NewItemController[FrrOspfNetwork, FrrOspfNetworkRow](c, "quagga/ospfsettings", "network", "Network", nil, "quagga/service/reconfigure"),
		OspfNeighbors:        NewItemController[FrrOspfNeighbor, FrrOspfNeighborRow](c, "quagga/ospfsettings", "neighbor", "Neighbor", nil, "quagga/service/reconfigure"),
		OspfInterfaces:       NewItemController[FrrOspfInterface, FrrOspfInterfaceRow](c, "quagga/ospfsettings", "interface", "Interface", nil, "quagga/service/reconfigure"),
		OspfPrefixLists:      NewItemController[FrrOspfPrefixList, FrrOspfPrefixListRow](c, "quagga/ospfsettings", "prefixlist", "Prefixlist", nil, "quagga/service/reconfigure"),
		OspfRouteMaps:        NewItemController[FrrOspfRouteMap, FrrOspfRouteMapRow](c, "quagga/ospfsettings", "routemap", "Routemap", nil, "quagga/service/reconfigure"),
		OspfRedistributions:  NewItemController[FrrOspfRedistribution, FrrOspfRedistributionRow](c, "quagga/ospfsettings", "redistribution", "Redistribution", nil, "quagga/service/reconfigure"),
		Ospf6Areas:           NewItemController[FrrOspf6Area, FrrOspf6AreaRow](c, "quagga/ospf6settings", "area", "Area", nil, "quagga/service/reconfigure"),
		Ospf6Interfaces:      NewItemController[FrrOspf6Interface, FrrOspf6InterfaceRow](c, "quagga/ospf6settings", "interface", "Interface", nil, "quagga/service/reconfigure"),
		Ospf6PrefixLists:     NewItemController[FrrOspf6PrefixList, FrrOspf6PrefixListRow](c, "quagga/ospf6settings", "prefixlist", "Prefixlist", nil, "quagga/service/reconfigure"),
		Ospf6RouteMaps:       NewItemController[FrrOspf6RouteMap, FrrOspf6RouteMapRow](c, "quagga/ospf6settings", "routemap", "Routemap", nil, "quagga/service/reconfigure"),
		Ospf6Redistributions: NewItemController[FrrOspf6Redistribution, FrrOspf6RedistributionRow](c, "quagga/ospf6settings", "redistribution", "Redistribution", nil, "quagga/service/reconfigure"),
		BfdNeighbors:         NewItemController[FrrBfdNeighbor, FrrBfdNeighborRow](c, "quagga/bfd", "neighbor", "Neighbor", nil, "quagga/service/reconfigure"),
		StaticRoutes:         NewItemController[FrrStaticRoute, FrrStaticRouteRow](c, "quagga/static", "route", "Route", nil, "quagga/service/reconfigure"),
		General:              NewSettingsController[FrrGeneral](c, "quagga/general/get", "quagga/general/set", []string{"general"}, "quagga/service/reconfigure"),
		BgpSettings:          NewSettingsController[FrrBgp](c, "quagga/bgp/get", "quagga/bgp/set", []string{"bgp"}, "quagga/service/reconfigure"),
		OspfSettings:         NewSettingsController[FrrOspf](c, "quagga/ospfsettings/get", "quagga/ospfsettings/set", []string{"ospf"}, "quagga/service/reconfigure"),
		Ospf6Settings:        NewSettingsController[FrrOspf6](c, "quagga/ospf6settings/get", "quagga/ospf6settings/set", []string{"ospf6"}, "quagga/service/reconfigure"),
		RipSettings:          NewSettingsController[FrrRip](c, "quagga/rip/get", "quagga/rip/set", []string{"rip"}, "quagga/service/reconfigure"),
		BfdSettings:          NewSettingsController[FrrBfd](c, "quagga/bfd/get", "quagga/bfd/set", []string{"bfd"}, "quagga/service/reconfigure"),
		StaticSettings:       NewSettingsController[FrrStatic](c, "quagga/static/get", "quagga/static/set", []string{"staticd"}, "quagga/service/reconfigure"),
	}
}
